parameters.inputSchema:
{
  "type": "array",
  "description": "List of all functions identified as performing slippage-sensitive actions (swap / add/remove liquidity / mint/burn LP / join/exit pool).",
  "items": {
    "type": "object",
    "additionalProperties": false,
    "required": ["code_snippet", "signature", "type", "description"],
    "properties": {
      "code_snippet": {
        "type": "string",
        "pattern": "^[A-Za-z_][A-Za-z0-9_]*\\.[A-Za-z_][A-Za-z0-9_]*$",
        "description": "Must be ContractName.FunctionName"
      },
      "signature": {
        "type": "string",
        "minLength": 1,
        "description": "Full Solidity function signature string."
      },
      "type": {
        "type": "string",
        "enum": [
          "swaps",
          "add_liquidity",
          "remove_liquidity",
          "mint_lp",
          "burn_lp",
          "join_pool",
          "exit_pool"
        ],
        "description": "Action type performed or directly triggered by this function."
      },
      "description": {
        "type": "string",
        "minLength": 1,
        "maxLength": 300,
        "description": "Brief reason why this function belongs to the specified type. Must mention the concrete call/action (e.g., router.swap, vault.joinPool/exitPool, poolAction.join/exit, add_liquidity/remove_liquidity, mint/burn LP as part of liquidity)."
      }
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": ["has_slippage_controls", "no_slippage_controls"],
  "properties": {
    "has_slippage_controls": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["code_snippet", "signature", "controls", "description"],
        "properties": {
          "code_snippet": {
            "type": "string",
            "pattern": "^[A-Za-z_][A-Za-z0-9_]*\\.[A-Za-z_][A-Za-z0-9_]*$",
            "description": "Must be BaseContract.EntryFunction"
          },
          "signature": {
            "type": "string",
            "minLength": 1
          },
          "controls": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["type", "name", "mechanism"],
              "properties": {
                "type": {
                  "type": "string",
                  "enum": ["minOut", "maxIn", "priceLimit", "deadline", "other"]
                },
                "name": {
                  "type": "string",
                  "minLength": 1,
                  "description": "Parameter/field/variable name used as a slippage-related control (e.g., amountOutMin, SwapParams.limit, sqrtPriceLimitX96)."
                },
                "mechanism": {
                  "type": "string",
                  "enum": ["passed", "checked", "both"]
                }
              }
            }
          },
          "description": {
            "type": "string",
            "minLength": 1,
            "maxLength": 300,
            "description": "Brief path-based explanation of what slippage bounds are enforced on the executed path. Mention the executed external call site(s) and which control(s) (minOut/maxIn/priceLimit/deadline/other) are passed/checked."
          }
        }
      }
    },
    "no_slippage_controls": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["code_snippet", "signature", "controls", "description"],
        "properties": {
          "code_snippet": {
            "type": "string",
            "pattern": "^[A-Za-z_][A-Za-z0-9_]*\\.[A-Za-z_][A-Za-z0-9_]*$",
            "description": "Must be BaseContract.EntryFunction"
          },
          "signature": {
            "type": "string",
            "minLength": 1
          },
          "controls": {
            "type": "array",
            "maxItems": 0,
            "items": false,
            "description": "Must be an empty array for the no_slippage_controls group."
          },
          "description": {
            "type": "string",
            "minLength": 1,
            "maxLength": 300,
            "description": "Brief path-based reason why this entry function lacks slippage controls. Mention executed call site(s) and the missing bound(s) (e.g., no minOut/maxIn/priceLimit). Do not speculate about opaque payloads or imported contract internals."
          }
        }
      }
    }
  }
}

parameters.text:
={{
  "## Stage 1 result (slippage classification)\n\n" +
  JSON.stringify({
    has_slippage_controls: (($json.output && $json.output.has_slippage_controls) || []),
    no_slippage_controls:  (($json.output && $json.output.no_slippage_controls)  || []),
  }, null, 2) +

  "\n\n## Base contract\n\n" + $json.base_contract +

  "\n\n## Imported contracts\n\n" +
  ($json.imported_contracts || []).map(c =>
    "=== " + c.source_path + " ===\n" + c.code
  ).join("\n\n")
}}

